void handle_vm_cmdSetFriendRemark(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 1) return;
    uint8_t n1 = body[0];
    if (1 + n1 > len) return;
    size_t off = 1 + n1;
    if (off >= len) return;
    uint8_t n2 = body[off++];
    if (off + n2 > len) return;
    applyLpc("cmd_set_friend_remark", {make_int(cl.clientNo), make_string(body + 1, n1), make_string(body + off, n2)});
}

